from pathlib import Path
from random import Random
p=Path(__file__).resolve().parents[1]/'assets'
r=Random(4217)
common='''<defs><radialGradient id="sky"><stop stop-color="#283759"/><stop offset="1" stop-color="#050b17"/></radialGradient><radialGradient id="planet" cx="25%" cy="15%" r="85%"><stop stop-color="#c2eeff"/><stop offset=".13" stop-color="#4d9bb9"/><stop offset=".35" stop-color="#154f76"/><stop offset=".7" stop-color="#0b223e"/><stop offset="1" stop-color="#020817"/></radialGradient><linearGradient id="metal" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#61839c"/><stop offset=".2" stop-color="#1e3149"/><stop offset=".5" stop-color="#0a1527"/><stop offset=".7" stop-color="#45607f"/><stop offset="1" stop-color="#090e1b"/></linearGradient><radialGradient id="cloud"><stop stop-color="#8e6ba0" stop-opacity=".6"/><stop offset="1" stop-color="#3c3670" stop-opacity="0"/></radialGradient><filter id="noise"><feTurbulence baseFrequency=".012 .024" numOctaves="4" seed="8"/><feColorMatrix values="0 0 0 0 .2 0 0 0 0 .5 0 0 0 0 .7 0 0 0 .6 0"/><feComposite in2="SourceGraphic" operator="in"/></filter><filter id="blur"><feGaussianBlur stdDeviation="6"/></filter><clipPath id="clip"><circle cx="270" cy="260" r="260"/></clipPath></defs>'''
def stars():
    return ''.join(f'<circle cx="{r.randrange(800)}" cy="{r.randrange(440)}" r="{r.choice([.4,.6,.9,1.1])}" fill="#bad5fc" opacity="{r.uniform(.2,.75):.2f}"/>' for _ in range(120))
def save(name,body):
    (p/name).write_text('<svg xmlns="http://www.w3.org/2000/svg" width="800" height="440" viewBox="0 0 800 440">'+common+'<rect width="800" height="440" fill="url(#sky)"/>'+stars()+body+'</svg>')
save('galaxies.svg','''<circle cx="270" cy="260" r="262" fill="#6ccfff" opacity=".3" filter="url(#blur)"/><circle cx="270" cy="260" r="260" fill="url(#planet)"/><g clip-path="url(#clip)"><circle cx="270" cy="260" r="260" filter="url(#noise)" opacity=".48"/>'''+''.join(f'<circle cx="{r.randrange(35,450)}" cy="{r.randrange(100,440)}" r="{r.uniform(.3,1):.2f}" fill="#90dcff" opacity="{r.uniform(.2,.8):.2f}"/>' for _ in range(250))+'''<path d="M-20 200Q220 90 510 240M-10 220Q240 120 520 280" fill="none" stroke="#acdfff" opacity=".2" stroke-width="8"/></g><ellipse cx="470" cy="390" rx="310" ry="90" fill="#040b1a" opacity=".35"/>''')
ring=''
for i in range(92):
    import math
    a=i*2*math.pi/92
    x=500+260*math.cos(a);y=170+110*math.sin(a)
    ring+=f'<path d="M{x:.1f} {y:.1f}l-14 35" stroke="#334b69" stroke-width="11"/><path d="M{x:.1f} {y:.1f}l-2 5" stroke="#a2cded" stroke-width="2"/>'
save('destinations.svg','''<ellipse cx="530" cy="120" rx="350" ry="230" fill="url(#cloud)"/><ellipse cx="500" cy="170" rx="260" ry="110" fill="none" stroke="url(#metal)" stroke-width="50" transform="rotate(-15 500 170)"/><g transform="rotate(-15 500 170)">'''+ring+'''<ellipse cx="500" cy="170" rx="230" ry="97" fill="none" stroke="#a5d4f0" stroke-opacity=".5" stroke-width="2"/><path d="M500 65V325M340 88l320 180M300 240l380-130" stroke="url(#metal)" stroke-width="12"/><path d="M495 130l65-8-20 120-65 8z" fill="url(#metal)"/><path d="M480 155l60-6M477 166l60-6M475 177l60-6" stroke="#a6d8ed" stroke-width="2"/></g><path d="m85 205 80-12 60 17-65 12z" fill="#415a73"/><path d="m160 216-115 8" stroke="#cfa2ff" stroke-width="2"/><path d="m380 340 350-50" stroke="#6d91b4" opacity=".3"/>''')
save('technology.svg','''<ellipse cx="460" cy="180" rx="370" ry="200" fill="url(#cloud)" opacity=".4"/><ellipse cx="460" cy="200" rx="305" ry="85" transform="rotate(-25 460 200)" fill="none" stroke="#6895cc" stroke-width="25" opacity=".18"/><ellipse cx="460" cy="200" rx="305" ry="85" transform="rotate(-25 460 200)" fill="none" stroke="#799bce" stroke-width="15" opacity=".5"/><circle cx="460" cy="200" r="118" fill="url(#planet)"/><circle cx="460" cy="200" r="118" filter="url(#noise)" opacity=".4"/><path d="M187 327Q590 336 733 70" fill="none" stroke="#849ccf" stroke-width="14" opacity=".65"/><path d="M181 335Q590 344 738 64" fill="none" stroke="#8bb6ef" stroke-width="1"/><path d="M166 349Q620 360 753 54" fill="none" stroke="#5e82bc" stroke-width="1" opacity=".5"/>''')
save('homeworld.svg','''<rect width="800" height="440" fill="#3a23452b"/><ellipse cx="480" cy="220" rx="420" ry="190" fill="url(#cloud)"/><circle cx="565" cy="80" r="53" fill="url(#planet)" opacity=".65"/><path d="M0 320 65 240 110 275 165 255 225 310 288 272 350 285 420 240 510 303 580 266 650 308 735 270 800 295V440H0Z" fill="#1b253a"/><path d="m0 360 110-55 78 35 150-37 143 50 105-39 90 52 124-45v119H0Z" fill="#101827"/><g transform="translate(396 160)"><ellipse cx="0" cy="23" rx="23" ry="26" fill="#9daab4"/><path d="M-18 8Q0-4 18 8v19l-36 4z" fill="#23334d"/><path d="m-22 47-10 70 17 7 3-41 3 55h29l-3-55 8 34 15-5-15-66z" fill="#728291"/><rect x="-17" y="48" width="37" height="59" rx="8" fill="#263a51"/><rect x="-12" y="55" width="27" height="37" rx="4" fill="#7b8d9f"/><circle cx="2" cy="72" r="8" fill="#81cee7"/><circle cx="2" cy="72" r="5" fill="#314b60"/><path d="m-11 135-7 47h15l8-43 8 43h15l-5-47z" fill="#6b7b8e"/><path d="m-18 182-8 8H0v-8m12 0-2 8h27l-10-8" fill="#263147"/></g><path d="m0 390 180-36 115 39 170-18 130 65H0z" fill="#090f1c"/>''')
(p/'favicon.svg').write_text('''<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="16" fill="#071124"/><circle cx="32" cy="32" r="16" fill="#264769" stroke="#b9eaff"/><ellipse cx="32" cy="32" rx="29" ry="9" fill="none" stroke="#c4c0ff" stroke-width="2" transform="rotate(-30 32 32)"/></svg>''')
